export const PREVIEW_DISABLED_TOOLTIP_MESSAGE: Record<
  Exclude<StateAccessType, "private">,
  string
> = {
  writable:
    "For the read and write states, the initial value depends on the variant. Therefore, you should set them in the settings tab.",
  readonly: "It is not possible to update a read-only state.",
};

export interface VariableValueEditorProps {
  state: State;
  component: Component;
  studioCtx: StudioCtx;
  viewCtx: ViewCtx;
  disableInitialValue?: boolean;
  initialValueAbout?: string;
  onChangeInitialValue?: (expr: Expr | undefined) => void;
  hidePreview?: boolean;
}

export interface StateVariableDraft {
  name: string;
  variableType: NormalStateVariableType;
  accessType: StateAccessType;
  initialValue: Expr | null;
}

export interface NewVariableProps extends DefaultNewVariableProps {
  state: State;
  component: Component;
  studioCtx: StudioCtx;
  viewCtx: ViewCtx;
  mode?: "new" | "edit";
  onCancel?: () => void;
  onConfirm?: () => void;
  onDraftChange?: (changes: Partial<StateVariableDraft>) => void;
}

export const VariableValueEditor = React.memo(function VariableValueEditor({
  component,
  state,
  studioCtx,
  viewCtx,
  disableInitialValue = false,
  initialValueAbout,
  onChangeInitialValue,
  hidePreview = false,
}: VariableValueEditorProps) {
  const { t: uiT } = useI18n();
  const inputs = useVariableRowInputs(viewCtx, component, state);
  const root = component.tplTree;
  assert(!inputs.invalidRoot && !isKnownTplSlot(root), "slots can't be root of a component");
  const [previewDraft, setPreviewDraft] = React.useState<Expr | undefined>(
    undefined,
  );
  const runtime = useInspectorStateValue(hidePreview ? undefined : viewCtx, state);
  const currentValue = runtime.value;
  const hasTempValue = runtime.hasTempValue;
  const previewExpr = previewDraft ?? code(currentValue === undefined ? "undefined" : jsLiteral(currentValue));
  const propType = wabTypeToPropType(
    convertVariableTypeToWabType(inputs.variableType),
  );

  const env = useInspectorCanvasEnv(hidePreview ? undefined : viewCtx, root) ?? {};

  return (
    <div
      style={{ position: "relative", width: "100%" }}
      className={"flex-col flex-fill"}
    >
      <div className={"mb-m"}>
        <PropEditorRow
          viewCtx={viewCtx}
          tpl={root}
          label={uiT("Initial Value")}
          attr="initial-value"
          expr={inputs.initialExpression ? studioCtx.modelSnapshots.resolve(inputs.initialExpression) : undefined}
          definedIndicator={{ source: "none" }}
          valueSetState={"isSet"}
          propType={propType}
          onChange={async (expr) => {
            const invalidMessage = validateStateAccessType(
              state.accessType,
              expr,
            );
            if (invalidMessage) {
              showError(invalidMessage, { title: uiT("Cannot set initial value") });
              return;
            }
            if (onChangeInitialValue) {
              onChangeInitialValue(expr);
              return;
            }
            await COMMANDS.component.changeStateInitialValue.execute(
              studioCtx,
              { expr },
              { state },
            );
          }}
          layout={"vertical"}
          disableLinkToProp={true}
          about={initialValueAbout}
          disabled={disableInitialValue}
        />
      </div>
      {!hidePreview &&
        !disableInitialValue &&
        runtime.hasUnstableInitializer && (
          <Alert
            className="mb-m"
            type="warning"
            showIcon
            message={uiT(
              "Unstable state initializers are not recommended. Use Side Effects for random or time based inputs.",
            )}
          />
        )}
      {!hidePreview && (
        <PropEditorRow
          viewCtx={viewCtx}
          tpl={root}
          label={uiT("Preview value")}
          attr="preview-value"
          about={
            inputs.implicitAccessType === "readonly"
              ? PREVIEW_DISABLED_TOOLTIP_MESSAGE.readonly
              : uiT(
                  "Temporarily set a value for this variable to preview how your component would look or behave.",
                )
          }
          disabled={
            inputs.implicitAccessType === "readonly"
          }
          expr={previewExpr}
          definedIndicator={
            hasTempValue && previewExpr
              ? {
                  source: "setNonVariable",
                  prop: "preview-value",
                  value: tryExtractString(previewExpr) || "",
                }
              : { source: "none" }
          }
          valueSetState={"isSet"}
          propType={propType}
          onChange={(_expr) => {
            if (!_expr) {
              return;
            }
            setPreviewDraft(_expr);
            const previewCode = getRawCode(_expr, {
              projectFlags: studioCtx.projectFlags(),
              component,
              inStudio: true,
            });
            const newValue = evalCodeWithEnv(previewCode, env);
            viewCtx.setCanvasStateValue(state, newValue);
          }}
          onDelete={() => {
            setPreviewDraft(undefined);
            viewCtx.resetCanvasStateValue(state);
          }}
          layout={"vertical"}
          disableLinkToProp={true}
          disableDynamicValue={true}
        />
      )}
    </div>
  );
});

const VariableEditingForm = React.memo(React.forwardRef(function VariableEditingForm(
    {
      component,
      state,
      studioCtx,
      viewCtx,
      mode = "edit",
      onCancel,
      onConfirm,
      onDraftChange,
      ...rest
    }: NewVariableProps,
    ref: HTMLElementRefOf<"div">,
  ) {
    const { t: uiT } = useI18n();
    const StringEditor = React.useCallback(
      ({
        label,
        onChange,
        value,
        "data-plasmic-prop": dataPlasmicProp,
      }: {
        label: React.ReactNode;
        onChange: (val: string) => void;
        value: string;
        "data-plasmic-prop"?: string;
      }) => (
        <LabeledItemRow layout={"vertical"} label={label}>
          <StringPropEditor
            onChange={onChange}
            value={value}
            valueSetState={"isSet"}
            disabled={false}
            data-plasmic-prop={dataPlasmicProp}
          />
        </LabeledItemRow>
      ),
      [],
    );

    const inputs = useVariableRowInputs(viewCtx, component, state);
    const hasExternalAccess = inputs.isExternal;
    return (
      <PlasmicNewVariable
        root={{ ref }}
        {...rest}
        variableName={
          <StringEditor
            label={inputs.implicit ? uiT("External name") : uiT("Name")}
            onChange={(val) =>
              onDraftChange
                ? onDraftChange({ name: val })
                : COMMANDS.component.changeStateVariableName.execute(
                    studioCtx,
                    {
                      varName: val,
                    },
                    {
                      state,
                      component,
                    },
                  )
            }
            data-plasmic-prop={"variable-name"}
            value={inputs.parameterName}
          />
        }
        variableType={{
          props: {
            value: inputs.variableType,
            "data-plasmic-prop": "variable-type",
            onChange: (val) =>
              onDraftChange
                ? val &&
                  onDraftChange({
                    variableType: val as NormalStateVariableType,
                    initialValue: codeLit(
                      getDefaultValueForStateVariableType(
                        val as NormalStateVariableType,
                      ),
                    ),
                  })
                : COMMANDS.component.changeStateVariableType.execute(
                    studioCtx,
                    {
                      type: val as NormalStateVariableType | null,
                    },
                    {
                      state,
                    },
                  ),
            children: NORMAL_STATE_VARIABLE_TYPES.map((stateType) => (
              <StyleSelect.Option value={stateType} key={stateType}>
                {L.startCase(stateType)}
              </StyleSelect.Option>
            )),
          },
        }}
        isPageComponent={inputs.isPage}
        variableInitVal={
          <VariableValueEditor
            state={state}
            component={component}
            studioCtx={studioCtx}
            viewCtx={viewCtx}
            hidePreview={mode === "new"}
            onChangeInitialValue={
              onDraftChange
                ? (expr) => onDraftChange({ initialValue: expr ?? null })
                : undefined
            }
          />
        }
        allowExternalAccess={{
          props: {
            isChecked: hasExternalAccess,
            onChange: (allow) => {
              if (onDraftChange) {
                onDraftChange({ accessType: allow ? "readonly" : "private" });
                return;
              }
              spawn(
                COMMANDS.component.changeStateVariableAccessType.execute(
                  studioCtx,
                  {
                    accessType: allow ? "readonly" : "private",
                  },
                  {
                    state,
                  },
                ),
              );
            },
            "data-test-id": "allow-external-access",
          },
        }}
        isExternal={hasExternalAccess}
        accessTypeSelect={{
          props: {
            "data-plasmic-prop": "access-type",
            value: inputs.accessType,
            onChange: async (val) => {
              const invalidMessage = validateStateAccessType(
                val as StateAccessType,
                state.param.defaultExpr,
              );
              if (invalidMessage) {
                showError(invalidMessage, { title: uiT("Cannot set access type") });
                return;
              }
              if (onDraftChange) {
                onDraftChange({ accessType: val as StateAccessType });
                return;
              }
              await COMMANDS.component.changeStateVariableAccessType.execute(
                studioCtx,
                {
                  accessType: val as StateAccessType,
                },
                {
                  state,
                },
              );
            },
            children: (
              [
                {
                  value: "readonly",
                  label: getAccessTypeDisplayName("readonly"),
                },
                {
                  value: "writable",
                  label: getAccessTypeDisplayName("writable"),
                },
              ] as { value: StateAccessType; label: string }[]
            ).map(({ label, value }) => (
              <StyleSelect.Option value={value} key={value}>
                {label}
              </StyleSelect.Option>
            )),
          },
        }}
        accessType={
          inputs.accessType === "private"
            ? "_private"
            : (inputs.accessType as Exclude<StateAccessType, "private">)
        }
        isImplicitState={inputs.hasTpl}
        withFormButtons={mode === "new"}
        cancelButton={{
          children: uiT("Cancel"),
          onClick: () => onCancel?.(),
        }}
        confirmButton={{
          props: {
            children: uiT("Confirm"),
            "data-test-id": "confirm",
            onClick: () => onConfirm?.(),
          },
        }}
      />
    );
  }));
export default VariableEditingForm;
